# Preserve conventional technical tokens, filenames, Markdown link targets and code spans.
protect=re.compile(r'(`+[^`\n]*`+|https?://[^\s)<>]+|\]\([^\n]*?\)|\b(?:SHEL5K|SH17|SHWD|SHD5000|CHV|SFCHD|PhysicalAI|LinQ|MOT17|MOT16|COCO2014|COCO2017|CC BY4.0|CC BY-NC4.0|CC BY-NC3.0|CC BY-NC-SA4.0|CC BY-NC-SA3.0)\b|\b(?:[A-Za-z_][\w.()-]*\.(?:json|txt|py|md|csv|jpg|jpeg|png|xml|mp4|zip|rar|gz))\b)',re.I)
def segment(word,vocab,allow_single=False):
    low=word.lower()
    if low in vocab or len(word)<7: return word
    n=len(word); dp=[None]*(n+1);dp[0]=(0,[])
    for i in range(n):
        if dp[i] is None:continue
        for j in range(i+1,n+1):
            s=low[i:j]
            if s not in vocab or (len(s)==1 and s not in ('и','в','с','к','у','о')):continue
            cost=dp[i][0]+4-math.log(min(vocab[s],100)+1)*.15
            if dp[j] is None or cost<dp[j][0]:dp[j]=(cost,dp[i][1]+[word[i:j]])
    return ' '.join(dp[n][1]) if dp[n] and len(dp[n][1])>1 else word
def plain(t):
    # Mixed-language and numeric adjacency is almost always a missing prose space.
    t=re.sub(r'([А-Яа-яЁё])([A-Za-z0-9])',r'\1 \2',t)
    t=re.sub(r'([A-Za-z0-9])([А-Яа-яЁё])',r'\1 \2',t)
    t=re.sub(r'(?<=[a-z])(?=[A-Z])',' ',t)
    t=re.sub(r'(\d)(?=[A-Za-z]{2})',r'\1 ',t)
    t=re.sub(r'([a-z]{3,})(?=\d)',r'\1 ',t)
    t=re.sub(r'[А-Яа-яЁё]+',lambda m:segment(m[0],v),t)
    t=re.sub(r'[A-Za-z]{7,}',lambda m:segment(m[0],ev),t)
    t=re.sub(r'\bне(?=(?:получен|проверен|выполнен|установлен|разрешен|объявлен|доказан|известен|определен|проведен))','не ',t)
    t=re.sub(r'([,;:])(?=[А-Яа-яЁёA-Za-z])',r'\1 ',t)
    return t
def normalize(text):
    chunks=protect.split(text)
    return ''.join(x if i%2 else plain(x) for i,x in enumerate(chunks))
if __name__=='__main__':
    for name in ['RAW_FACTS.md','SOURCES.md']:
        p=R/name;p.write_text(normalize(p.read_text(encoding='utf-8')),encoding='utf-8')
